        }}

        .content {{
            padding: 40px;
        }}

        .section {{
            margin-bottom: 40px;
        }}

        .section h2 {{
            color: #006633;
            font-size: 1.8em;
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 3px solid #FFB81C;
        }}

        .section h3 {{
            color: #2d5f3d;
            font-size: 1.3em;
            margin: 25px 0 15px 0;
        }}

        .match-card {{
            background: #f8f9fa;
            border-left: 5px solid #006633;
            padding: 20px;
            margin-bottom: 20px;
            border-radius: 5px;
        }}

        .match-header {{
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 15px;
            flex-wrap: wrap;
        }}

        .match-date {{
            color: #666;
            font-size: 0.9em;
        }}

        .match-opponent {{
            font-size: 1.4em;
            font-weight: bold;
            color: #006633;
        }}

        .match-score {{
            font-size: 2em;
            font-weight: bold;
            color: #FFB81C;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.1);
        }}

        .match-details {{
            margin: 15px 0;
            padding: 15px;
            background: white;
            border-radius: 5px;
        }}

        .lineup-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
            gap: 10px;
            margin: 15px 0;
        }}

        .player-item {{
            background: #e8f5e9;
            padding: 10px;
            border-radius: 5px;
            border-left: 3px solid #006633;
        }}

        .player-position {{
            font-weight: bold;
            color: #006633;
            font-size: 0.85em;
        }}

        .player-name {{
            color: #333;
            margin-top: 3px;
        }}

        .stats-list {{
            list-style: none;
            padding: 0;
        }}

        .stats-list li {{
            padding: 8px 0;
            border-bottom: 1px solid #eee;
        }}

        .stats-list li:last-child {{
            border-bottom: none;
        }}

        .try-scorer {{
            display: inline-block;
            background: #FFB81C;
            color: #333;
            padding: 5px 10px;
            margin: 5px;
            border-radius: 3px;
            font-weight: bold;
        }}

        .recommendation-box {{
            background: #e3f2fd;
            border-left: 5px solid #1976d2;
            padding: 20px;
            margin: 15px 0;
            border-radius: 5px;
        }}

        .advice-section {{
            background: #fff3e0;
            border-left: 5px solid #f57c00;
            padding: 20px;
            margin: 15px 0;
            border-radius: 5px;
            white-space: pre-wrap;
            font-family: 'Courier New', monospace;
            line-height: 1.8;
        }}

        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
        }}

        th {{
            background: #006633;
            color: white;
            padding: 12px;
            text-align: left;
            font-weight: bold;
        }}

        td {{
            padding: 10px 12px;
            border-bottom: 1px solid #ddd;
        }}

        tr:hover {{
            background: #f5f5f5;
        }}

        .footer {{
            background: #f8f9fa;
            padding: 20px;
            text-align: center;
            color: #666;
            font-size: 0.9em;
        }}

        .win {{
            color: #2e7d32;
            font-weight: bold;
        }}

        .loss {{
            color: #c62828;
            font-weight: bold;
        }}

        @media print {{
            body {{
                background: white;
                padding: 0;
            }}

            .container {{
                box-shadow: none;
            }}
        }}
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>🏉 Springbok Performance Analysis</h1>
            <div class="subtitle">Team Selection Report for Rassie Erasmus</div>
            <div class="date">Generated: {datetime.now().strftime('%B %d, %Y at %H:%M')}</div>
        </div>

        <div class="content">
            <!-- Recent Match Results Summary -->
            <div class="section">
                <h2>📊 Recent Match Results Summary</h2>
                <table>
                    <thead>
                        <tr>
                            <th>Date</th>
                            <th>Opponent</th>
                            <th>Score</th>
                            <th>Result</th>
                            <th>Competition</th>
                            <th>Venue</th>
                        </tr>
                    </thead>
                    <tbody>
"""

for match in matches:
    sa_score = match.get("score_sa", 0)
    opp_score = match.get("score_opponent", 0)
    result = "WIN" if sa_score > opp_score else "LOSS" if sa_score < opp_score else "DRAW"
    result_class = "win" if result == "WIN" else "loss"

    html_content += f"""
                        <tr>
                            <td>{match.get('date', 'N/A')}</td>
                            <td><strong>{match.get('opponent', 'N/A')}</strong></td>
                            <td><strong>{sa_score} - {opp_score}</strong></td>
                            <td class="{result_class}">{result}</td>
                            <td>{match.get('competition', 'N/A')}</td>
                            <td>{match.get('venue', 'N/A')}</td>
                        </tr>
"""

html_content += """
                    </tbody>
                </table>
            </div>

            <!-- Detailed Match Breakdowns -->
            <div class="section">
                <h2>🔍 Detailed Match Breakdowns</h2>
"""

for i, match in enumerate(matches, 1):
    sa_score = match.get("score_sa", 0)
    opp_score = match.get("score_opponent", 0)
    result = "WIN" if sa_score > opp_score else "LOSS" if sa_score < opp_score else "DRAW"

    html_content += f"""
                <div class="match-card">
                    <div class="match-header">
                        <div>
                            <div class="match-date">{match.get('date', 'N/A')} • {match.get('competition', 'N/A')}</div>
                            <div class="match-opponent">South Africa vs {match.get('opponent', 'N/A')}</div>
                        </div>
                        <div class="match-score">{sa_score} - {opp_score}</div>
                    </div>

                    <div class="match-details">
                        <p><strong>Venue:</strong> {match.get('venue', 'N/A')}</p>
                        <p><strong>Result:</strong> <span class="{'win' if result == 'WIN' else 'loss'}">{result}</span></p>
                    </div>

                    <h3>Starting XV</h3>
                    <div class="lineup-grid">
"""

    starting_xv = match.get("starting_xv", {})
    for pos in range(1, 16):
        player = starting_xv.get(str(pos), f"Player {pos}")
        position_names = {
            "1": "Loosehead Prop", "2": "Hooker", "3": "Tighthead Prop",
            "4": "Lock", "5": "Lock", "6": "Blindside Flanker",
            "7": "Openside Flanker", "8": "Number 8", "9": "Scrum-half",
            "10": "Fly-half", "11": "Left Wing", "12": "Inside Centre",
            "13": "Outside Centre", "14": "Right Wing", "15": "Fullback"
        }
        html_content += f"""
                        <div class="player-item">
                            <div class="player-position">{pos}. {position_names.get(str(pos), f'Position {pos}')}</div>
                            <div class="player-name">{player}</div>
                        </div>
"""

    html_content += """
                    </div>
"""

    # Try scorers
    try_scorers = match.get("try_scorers", [])
    if try_scorers:
        html_content += """
                    <h3>🎯 Try Scorers</h3>
                    <div>
"""
        for try_scorer in try_scorers:
            player = try_scorer.get("player", "Unknown")
            minute = try_scorer.get("minute", "")
            html_content += f'<span class="try-scorer">{player} {minute}</span>\n'

        html_content += """
                    </div>
"""

    # Key performers
    key_performers = match.get("key_performers", [])
    if key_performers:
        html_content += """
                    <h3>⭐ Key Performers</h3>
                    <ul class="stats-list">
"""
        for performer in key_performers:
            html_content += f"<li>{performer}</li>\n"
        html_content += """
                    </ul>
"""

    # Injuries and cards
    injuries = match.get("injuries", [])
    cards = match.get("cards", [])

    if injuries or cards:
        html_content += """
                    <h3>⚠️ Injuries & Discipline</h3>
                    <ul class="stats-list">
"""
        for injury in injuries:
            html_content += f"<li>🏥 {injury}</li>\n"
        for card in cards:
            html_content += f"<li>🟨 {card}</li>\n"
        html_content += """
                    </ul>
"""

    html_content += """
                </div>
"""

html_content += """
            </div>

            <!-- Player Performance Analysis -->
            <div class="section">
                <h2>👥 Player Performance Analysis</h2>

                <h3>Consistency Analysis</h3>
                <table>
