                            <th>Player</th>
                            <th>Starts</th>
                            <th>Positions Played</th>
                            <th>Last Appearance</th>
                        </tr>
                    </thead>
                    <tbody>
"""

# Sort players by number of starts
sorted_players = sorted(player_appearances.items(), 
                       key=lambda x: x[1]["starts"], 
                       reverse=True)[:20]  # Top 20 players

for player, stats in sorted_players:
    positions = ", ".join(set(stats["positions"]))
    last_match = max(stats["matches"]) if stats["matches"] else "N/A"
    html_content += f"""
                        <tr>
                            <td><strong>{player}</strong></td>
                            <td>{stats["starts"]}</td>
                            <td>{positions}</td>
                            <td>{last_match}</td>
                        </tr>
"""

html_content += f"""
                    </tbody>
                </table>
            </div>

            <!-- Team Selection Recommendations -->
